//! Additive native generation; the original 36 ABI1 declarations stay separate.
#[cfg(all(not(target_arch = "wasm32"), feature = "sdk-types"))]
fn main() {
    use editor_kwdj_sdk::wire_v2::KwdjClipboardIntentV2;
    use klenwriter_editor_wasm::sdk_wire::BridgeRequest;
    use klenwriter_editor_wasm::sdk_wire::v2::*;
    use ts_rs::{Config, TS};
    let config = Config::default();
    println!(
        "// Generated by ts-rs 12.0.1 from protocol V2, optional KWDJ V2 and common BridgeRequest. Do not edit."
    );
    println!(
        "import type {{ AccessDto, AdmissionDto, CommandDto, DiagnosticDto, ExtensionDto, HistoryDirectionDto, HistoryHintDto, MarkDto, PositionDto, ProfileDto, SdkReply, SelectionDto, StampDto }} from './sdk-types.js';\n"
    );
    macro_rules! emit {
        ($($name:ty),* $(,)?) => { $(println!("export {}\n", <$name>::decl(&config));)* };
    }
    emit!(
        CompiledProfileV2,
        SdkManifestV2,
        OpenOptionsV2,
        SessionContextV2,
        KwdjClipboardIntentV2,
        ClipboardContextRequestV2,
        ClipboardContextReplyV2,
        SelectionFragmentRequestV2,
        SelectionFragmentReplyV2,
        BridgeRequest,
        TextWindowRequestV2,
        TextWindowReplyV2,
        TextWindowSpanV2,
        TextWindowNodeV2,
        TextWindowBoundaryV2,
        SelectionTextRequestV2,
        SelectionTextReplyV2,
        BridgeRequestV2,
        SdkReplyV2,
        SdkResponseV2
    );
}

